import{_ as a,o as e,c as i,a0 as r}from"./chunks/framework.jwovEGr5.js";const y=JSON.parse('{"title":"Product finality + OS parity","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/FINALITY.md","filePath":"deploy/FINALITY.md"}'),s={name:"deploy/FINALITY.md"};function d(o,t,n,l,h,c){return e(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="product-finality-os-parity" tabindex="-1">Product finality + OS parity <a class="header-anchor" href="#product-finality-os-parity" aria-label="Permalink to &quot;Product finality + OS parity&quot;">​</a></h1><p>sharecli ships <strong>three product lanes</strong> with explicit finality, and a <strong>four-host parity floor</strong> (macOS · Windows · Linux · WSL). Native stacks stay optimal per OS; nothing below the floor is “MVP complete.”</p><h2 id="finality-lanes" tabindex="-1">Finality lanes <a class="header-anchor" href="#finality-lanes" aria-label="Permalink to &quot;Finality lanes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lane</th><th>Product</th><th>Finality</th><th>Notes</th></tr></thead><tbody><tr><td>A</td><td>CLI + <code>sharecli serve</code></td><td><strong>GA</strong></td><td>Unsigned archives OK until L112 signing</td></tr><tr><td>B</td><td>Native tray / menubar</td><td><strong>Beta</strong></td><td>Per-OS native UI; WSL via bridge</td></tr><tr><td>C</td><td>Dashboard / status UI</td><td><strong>Beta floor</strong></td><td>Web cockpit everywhere; macOS native <code>DashboardView</code> is the optimality peak</td></tr></tbody></table><p>Do <strong>not</strong> claim GA for tray/desktop until codesign/notarize (L112) and classic installers (L108) land.</p><h2 id="parity-floor-every-host" tabindex="-1">Parity floor (every host) <a class="header-anchor" href="#parity-floor-every-host" aria-label="Permalink to &quot;Parity floor (every host)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Requirement</th></tr></thead><tbody><tr><td>CLI install + <code>serve</code></td><td>Same flags; <code>GET /healthz</code> / <code>/readyz</code>; OpenAPI contract</td></tr><tr><td>Process list / stop / status</td><td>Same CLI verbs + IPC schema</td></tr><tr><td>Tray / menubar</td><td>Visible status item on GUI hosts</td></tr><tr><td>Dashboard</td><td>One click from tray <strong>or</strong> <code>http://127.0.0.1:9000/</code></td></tr><tr><td>Release artifact</td><td>Downloadable archive <strong>or</strong> documented WSL→host bridge</td></tr><tr><td>Docs</td><td>This file + <a href="./../deploy.html"><code>deploy.md</code></a> row per host</td></tr></tbody></table><h2 id="maximum-optimality-per-os" tabindex="-1">Maximum optimality per OS <a class="header-anchor" href="#maximum-optimality-per-os" aria-label="Permalink to &quot;Maximum optimality per OS&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Host</th><th>Optimal stack</th><th>Parity path</th></tr></thead><tbody><tr><td><strong>macOS</strong></td><td>Swift <a href="https://github.com/KooshaPari/sharecli/tree/main/desktop/ShareCLITray" target="_blank" rel="noreferrer"><code>desktop/ShareCLITray</code></a> — NSStatusItem + NSPopover + <code>DashboardView</code></td><td>Exceeds floor (native desktop window)</td></tr><tr><td><strong>Windows</strong></td><td>WinUI <a href="https://github.com/KooshaPari/sharecli/tree/main/windows/ShareCLITray" target="_blank" rel="noreferrer"><code>windows/ShareCLITray</code></a> + CLI zip; open web cockpit from tray</td><td>Tray + dashboard</td></tr><tr><td><strong>Linux</strong></td><td><a href="https://github.com/KooshaPari/sharecli/tree/main/crates/sharecli-tray-linux" target="_blank" rel="noreferrer"><code>sharecli-tray-linux</code></a> (StatusNotifier) + CLI tarball; tray opens web cockpit</td><td>Tray + dashboard</td></tr><tr><td><strong>WSL</strong></td><td>CLI <strong>inside</strong> WSL; tray/dashboard via <strong>Windows tray → forwarded port</strong> (preferred) or WSLg + Linux tray</td><td>Equal capabilities through bridge</td></tr></tbody></table><p>Do not unify on Electron/Tauri for MVP — that trades away per-OS optimality.</p><h2 id="wsl-bridge-parity" tabindex="-1">WSL bridge (parity) <a class="header-anchor" href="#wsl-bridge-parity" aria-label="Permalink to &quot;WSL bridge (parity)&quot;">​</a></h2><ol><li>In WSL: <code>sharecli serve --bind 0.0.0.0:9000</code></li><li>From Windows: open <code>http://127.0.0.1:9000/</code> (mirrored localhost) <strong>or</strong> run <code>ShareCLITray</code> against the WSL-published port.</li><li>Optional: WSLg + <code>sharecli-tray-linux</code> if a Linux desktop session is available.</li></ol><p>Smoke: <code>curl -fsS http://127.0.0.1:9000/healthz</code> from both WSL and Windows.</p><h2 id="local-builds" tabindex="-1">Local builds <a class="header-anchor" href="#local-builds" aria-label="Permalink to &quot;Local builds&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-tray-linux</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # Linux host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-tray-macos</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # macOS: ffi + Swift (tray + desktop)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-tray-windows</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Windows: WinUI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wsl-parity-check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # prints bridge checklist</span></span></code></pre></div><h2 id="ci-artifacts" tabindex="-1">CI artifacts <a class="header-anchor" href="#ci-artifacts" aria-label="Permalink to &quot;CI artifacts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Job / artifact prefix</th><th>Host</th><th>Lane</th></tr></thead><tbody><tr><td><code>sharecli-*-unknown-linux-gnu</code></td><td>Linux CLI</td><td>A</td></tr><tr><td><code>sharecli-*-apple-darwin</code></td><td>macOS CLI</td><td>A</td></tr><tr><td><code>sharecli-*-pc-windows-msvc</code></td><td>Windows CLI</td><td>A</td></tr><tr><td><code>sharecli-tray-linux-*</code></td><td>Linux tray</td><td>B</td></tr><tr><td><code>sharecli-desktop-macos-*</code></td><td>macOS tray+desktop</td><td>B+C</td></tr><tr><td><code>sharecli-tray-windows-*</code></td><td>Windows tray</td><td>B</td></tr></tbody></table><p>See <code>.github/workflows/desktop-builds.yml</code> (PR smoke) and <code>release.yml</code> (tag/dispatch attach).</p>`,18)])])}const b=a(s,[["render",d]]);export{y as __pageData,b as default};
